/**
 * /colophon's original-work manifest (static/data/original-work.json, generated by
 * scripts/build-original-work.mjs) and its locale overlay
 * (i18n-src/<locale>/original-work.json): per section, entries keyed by
 * `originalWorkKey` → translated title / what / where. Routes, files and thumbnails
 * stay shared.
 */
export type OriginalWorkEntry = {
  title: string;
  what?: string;
  where?: string;
  route?: string;
  file?: string;
  thumb?: string;
};
export type OriginalWorkManifest = Record<string, OriginalWorkEntry[] | unknown>;
export type OriginalWorkOverlay = Record<
  string,
  Record<string, { title?: string; what?: string; where?: string }>
>;

/** An entry's stable key within its section: routes repeat (/fly), so the file or
 *  thumbnail when there is one, else the English title — with dots replaced, since
 *  the translators address fields by dotted path. */
export function originalWorkKey(e: OriginalWorkEntry): string {
  return (e.file || e.thumb || e.title).replace(/\./g, '_');
}

/** Merge a locale overlay; missing fields keep the English. */
export function localizeOriginalWork<T extends OriginalWorkManifest>(
  m: T,
  overlay: OriginalWorkOverlay | null | undefined,
): T {
  if (!overlay) return m;
  const out: Record<string, unknown> = { ...m };
  for (const [section, entries] of Object.entries(m)) {
    const o = overlay[section];
    if (!o || !Array.isArray(entries)) continue;
    out[section] = (entries as OriginalWorkEntry[]).map((e) => {
      const t = o[originalWorkKey(e)];
      if (!t) return e;
      return {
        ...e,
        ...(t.title ? { title: t.title } : {}),
        ...(t.what && e.what ? { what: t.what } : {}),
        ...(t.where && e.where ? { where: t.where } : {}),
      };
    });
  }
  return out as T;
}
